/// PushHub routing envelope; execution identity never replaces the subscription key.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct PushTransportEnvelope {
    /// PushHub subscription channel; payload cannot override it.
    #[serde(rename = "channel")]
    pub channel: String,
    /// PushHub subscription key, not necessarily the producing execution task.
    #[serde(rename = "taskId")]
    pub task_id: String,
    /// Producing execution task id when different from the subscription key.
    #[serde(
        rename = "executionTaskId",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub execution_task_id: Option<String>,
    /// Canonical conversation owner of a mirrored task event; never inferred from an execution id.
    #[serde(
        rename = "conversationId",
        default,
        skip_serializing_if = "Option::is_none"
    )]
    pub conversation_id: Option<String>,
}

